const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo(resolve, reject);
  });
}

function getYearCollection(datasetId, year, region) {
  const start = ee.Date.fromYMD(year, 1, 1);
  const end = ee.Date.fromYMD(year + 1, 1, 1);
  return ee.ImageCollection(datasetId)
    .filterDate(start, end)
    .filterBounds(region)
    .select(['LC_Type1']);
}

async function getYearImage(year, region) {
  const datasets = ['MODIS/061/MCD12Q1', 'MODIS/006/MCD12Q1'];
  for (let i = 0; i < datasets.length; i++) {
    const ds = datasets[i];
    const col = getYearCollection(ds, year, region);
    const size = await getInfoAsync(col.size());
    if (size && size > 0) {
      return { image: col.first(), dataset: ds, size: size };
    }
  }
  return { image: null, dataset: null, size: 0 };
}

async function computeCropStats(img, region) {
  // Cropland classes in IGBP (LC_Type1): 12=Croplands, 14=Cropland/Natural vegetation mosaic
  const lc = img.select('LC_Type1');
  const cropMask = lc.eq(12).or(lc.eq(14));
  const scale = 1000; // per requirement: >=1000
  const countDict = cropMask.updateMask(cropMask)
    .rename('mask')
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e13,
      bestEffort: true,
      tileScale: 4
    });
  const count = await getInfoAsync(countDict.get('mask'));
  const areaDict = ee.Image.pixelArea()
    .updateMask(cropMask)
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: scale,
      maxPixels: 1e13,
      bestEffort: true,
      tileScale: 4
    });
  const area_m2 = await getInfoAsync(areaDict.get('area'));
  let area_km2 = null;
  if (area_m2 !== null && area_m2 !== undefined) {
    area_km2 = area_m2 / 1e6;
  }
  return { count: count || 0, area_km2 };
}

async function runAnalysis() {
  try {
    // 1. Geometry & Years
    const africa = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
      .filter(ee.Filter.eq('wld_rgn', 'Africa'))
      .geometry();

    const yearA = 2003;
    const yearB = 2019;

    console.log('Dataset: MODIS MCD12Q1 (LC_Type1 IGBP; crops=12,14)');
    console.log('Region: Africa (USDOS/LSIB_SIMPLE/2017), Scale: 1000 m');

    // 2. Acquire images with fallback
    const yA = await getYearImage(yearA, africa);
    const yB = await getYearImage(yearB, africa);

    console.log(`${yearA} Images: ${yA.size} ${yA.dataset ? '(' + yA.dataset.split('/')[1] + ')' : ''}`);
    console.log(`${yearB} Images: ${yB.size} ${yB.dataset ? '(' + yB.dataset.split('/')[1] + ')' : ''}`);

    if (!yA.image || !yB.image) {
      console.log('One or both years have empty collections after fallback.');
      console.log('C1: Empty Collection');
      return;
    }

    // 3. Compute stats
    const statsA = await computeCropStats(yA.image, africa);
    const statsB = await computeCropStats(yB.image, africa);

    // 4. Validate pixel counts
    if ((statsA.count || 0) === 0 || (statsB.count || 0) === 0) {
      console.log(`Valid crop pixels -> ${yearA}: ${statsA.count}, ${yearB}: ${statsB.count}`);
      console.log('C2: No Valid Pixels');
      return;
    }

    // 5. Validate areas
    const aA = statsA.area_km2;
    const aB = statsB.area_km2;
    const invalid =
      aA === null || aB === null ||
      !isFinite(aA) || !isFinite(aB) ||
      aA < 0 || aB < 0 || aA > 4e7 || aB > 4e7;

    console.log(`${yearA} Crop Pixels: ${statsA.count}, Area_km2: ${aA ? aA.toFixed(0) : 'null'}`);
    console.log(`${yearB} Crop Pixels: ${statsB.count}, Area_km2: ${aB ? aB.toFixed(0) : 'null'}`);

    if (invalid) {
      console.log('C3: Calculation Failure');
      return;
    }

    // 6. Compare
    const diff = aB - aA;
    const threshold = 400000; // km^2
    console.log(`Δ Area (2019-2003) km2: ${diff.toFixed(0)} vs threshold ${threshold}`);

    if (diff > threshold) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
